use super::*;
fn complete(dir:&Path,kind:&str)->Result<Json>{let r=load(&dir.join(match kind{"life"=>"life.json","preview"=>"preview.json",_=>"creative.json"}))?;require(s(&r,"status")?==if flag(&r,"mock"){"technical_rehearsal_complete"}else{"collected_unrated"},"Complete collection required")?;if kind=="life"{require(r.get("planned_proposals")?==r.get("completed_proposals")?,"Incomplete proposal collection")?;}Ok(r)}
pub(super) fn mapped(dir:&Path,kind:&str)->Result<(Json,Vec<Json>,Vec<Json>,BTreeMap<String,Json>)>{let report=complete(dir,kind)?;let trials=if kind=="creative"{read_lines(&dir.join("creative-proposals.jsonl"))?}else{load(&dir.join("all-proposals.json"))?.array()?.to_vec()};let pack=load(&dir.join("blind-proposals.json"))?.array()?.to_vec();let key=load(&dir.join("private-blind-key.json"))?;require(!trials.is_empty()&&trials.len()==pack.len()&&key.array()?.len()==pack.len(),"Invalid blind pack coverage")?;if kind=="preview"{require(trials.len()==60,"Preview requires 60 proposals")?;}if kind=="life"{require(trials.len() as f64==n(&report,"planned_proposals")?,"Incomplete life proposal coverage")?;}
 let mut by_trial=BTreeMap::new();for t in &trials{require(by_trial.insert(s(t,"trial_id")?.to_owned(),t.clone()).is_none(),"Duplicate trial")?;}let mut mapping=BTreeMap::new();let mut seen=BTreeSet::new();for k in key.array()?{let id=s(k,"id")?;let trial=s(k,"trial_id")?;require(seen.insert(trial)&&by_trial.contains_key(trial),"Invalid trial mapping")?;require(mapping.insert(id.to_owned(),by_trial[trial].clone()).is_none(),"Duplicate blind mapping")?;}
 let mut ids=BTreeSet::new();for p in &pack{let id=s(p,"id")?;require(ids.insert(id)&&mapping.contains_key(id),"Invalid blind proposal ID")?;}Ok((report,trials,pack,mapping))}
fn scored(pack:&[Json],mapping:&BTreeMap<String,Json>,ratings:&Json,kind:&str)->Result<Vec<Json>>{let mut by_id:BTreeMap<String,Vec<&Json>>=BTreeMap::new();let mut seen=BTreeSet::new();for r in ratings.array()?{let id=s(r,"id")?;let rater=s(r,"rater")?;require(mapping.contains_key(id),"Unknown proposal")?;require(!rater.trim().is_empty(),"Rater ID required")?;require(seen.insert((id.to_string(),rater.to_string())),"Duplicate rating")?;for axis in ["utility","originality"]{let x=n(r,axis)?;require(x.is_finite()&&x.fract()==0.&&(0. ..=4.).contains(&x),"Ordinal 0..4 required")?;}require(matches!(r.get("constraints_met")?,Json::Bool(_)),"Boolean constraint result required")?;require(!s(r,"rationale")?.trim().is_empty(),"Rationale required")?;by_id.entry(id.into()).or_default().push(r);}
 pack.iter().map(|entry|{let id=s(entry,"id")?;let rs=by_id.get(id).ok_or("Two independent raters required")?;require(rs.len()>=2,"Two independent raters required")?;let t=&mapping[id];let valid=t.get("generation")?.get("valid").ok()!=Some(&Json::Bool(false));if kind=="preview"{require(matches!(t.get("generation")?.get("valid")?,Json::Bool(_)),"Preview validity flag required")?;}
 let utility=rs.iter().map(|r|n(r,"utility")).collect::<Result<Vec<_>>>()?;let originality=rs.iter().map(|r|n(r,"originality")).collect::<Result<Vec<_>>>()?;let scores=rs.iter().enumerate().map(|(i,r)|if valid&&flag(r,"constraints_met"){utility[i].min(originality[i])}else{0.}).collect::<Vec<_>>();let disagreement=scores.iter().copied().fold(f64::NEG_INFINITY,f64::max)-scores.iter().copied().fold(f64::INFINITY,f64::min);
 let mut row=obj([("id",text(id)),("task",t.get("task")?.get("id")?.clone()),("condition",t.get("condition")?.clone()),("repeat",t.get("repeat")?.clone()),("utility",num(mean(&utility))),("originality",num(mean(&originality))),("creative_score",num(mean(&scores)))]);
 if kind=="life"{for k in ["pair","branch","day","phase"]{row.put(k,t.get(k)?.clone());}row.put("format_valid",Json::Bool(valid));row.put("disagreement",num(disagreement));}else{row.put("history",t.get("history")?.clone());row.put("rater_disagreement",num(disagreement));if kind=="preview"{row.put("valid",Json::Bool(valid));}}Ok(row)
 }).collect()}
fn stats(xs:&[&Json])->Result<Json>{require(!xs.is_empty(),"Missing condition")?;let mut row=obj([("n",num(xs.len() as f64))]);for k in ["utility","originality","creative_score"]{row.put(k,num(mean(&xs.iter().map(|x|n(x,k)).collect::<Result<Vec<_>>>()?)));}Ok(row)}
pub(super) fn analyze(dir:&Path,ratings:&Json,kind:&str)->Result<Json>{let (report,_trials,pack,mapping)=mapped(dir,kind)?;let rows=scored(&pack,&mapping,ratings,kind)?;let mock=flag(&report,"mock");let hash=file_hash(&dir.join("all-proposals.json")).ok();
 if kind!="life"{let histories=rows.iter().map(|r|s(r,"history")).collect::<Result<BTreeSet<_>>>()?;if kind=="preview"{require(histories.len()==2,"Preview requires two histories")?;}let conditions=if kind=="preview"{vec!["empty","rag","before_sleep","after_no_recon","after_full"]}else{vec!["empty","rag","selmem_no_recon","selmem_full"]};let mut per=vec![];
 for history in &histories{let mut by=BTreeMap::new();for c in &conditions{let xs=rows.iter().filter(|r|s(r,"history").ok()==Some(*history)&&s(r,"condition").ok()==Some(*c)).collect::<Vec<_>>();if kind=="preview"{require(xs.len()==6,"Missing preview condition cells")?;let cells=xs.iter().map(|r|Ok((s(r,"task")?,n(r,"repeat")?.to_bits()))).collect::<Result<BTreeSet<_>>>()?;require(cells.len()==6,"Duplicate task/repeat cells")?;}by.insert(c.to_string(),stats(&xs)?);}let full=n(&by[if kind=="preview"{"after_full"}else{"selmem_full"}],"creative_score")?;let mut row=obj([("history",text(*history)),("by_condition",Json::Object(by.clone())),("full_minus_rag",num(full-n(&by["rag"],"creative_score")?))]);if kind=="preview"{for (field,c) in [("full_minus_empty","empty"),("sleep_difference","before_sleep"),("probe_reconstruction_difference","after_no_recon")]{row.put(field,num(full-n(&by[c],"creative_score")?));}}else{row.put("full_minus_no_recon",num(full-n(&by["selmem_no_recon"],"creative_score")?));}per.push(row);}
 let mut result=obj([("version",text(if kind=="preview"{"creative-preview-ratings-1"}else{"creative-ratings-1"})),("mock",Json::Bool(mock)),("status",text(if mock{"technical_rehearsal_only"}else{"exploratory_blind_ratings"})),("histories",num(histories.len() as f64)),("proposals",num(rows.len() as f64)),("per_history",arr(per)),("scored",arr(rows))]);if kind=="preview"{result.put("source_proposals_sha256",text(hash.ok_or("missing source hash")?));result.put("interpretation",text("Two source histories are the independent units. Generation repeats and empty baselines are not independent lives. The before_sleep arm has the same elapsed time but no sleep. Mean min(utility, originality), invalid outputs/constraint violations zero, is an operational ordinal score. No significance, worldwide novelty, causal source attribution or unconsciousness verdict."));}else{result.put("primary_metric",text("Mean min(utility, originality), zero if constraints fail; ordinal 0..4, not validated creativity scale."));result.put("interpretation",text("Independent unit is a conversation history. Generation repeats are paired samples, not independent lives. This file does not establish source recombination, causal attribution, worldwide novelty or statistical significance. Blind judges require no access to private key, readouts or responses. RAG/empty repeats are controls for generation variability."));}return Ok(result);
 }
 let mut grouped:BTreeMap<String,Vec<&Json>>=BTreeMap::new();for row in &rows{let key=arr(["pair","branch","day","phase","condition"].map(|k|row.get(k).unwrap().clone())).encode();grouped.entry(key).or_default().push(row);}let mut cells=vec![];for xs in grouped.values(){let mut c=stats(xs)?;for k in ["pair","branch","day","phase","condition"]{c.put(k,xs[0].get(k)?.clone());}cells.push(c);}
 let pairs=rows.iter().map(|r|s(r,"pair")).collect::<Result<BTreeSet<_>>>()?;let mut contrasts=vec![];for pair in &pairs{let days=cells.iter().filter(|c|s(c,"pair").ok()==Some(*pair)&&s(c,"phase").ok()==Some("primary")).map(|c|n(c,"day").map(|d|d as usize)).collect::<Result<BTreeSet<_>>>()?;for day in days{let mut differences=BTreeMap::new();for control in ["replica","probe_no_recon","no_sleep","no_recon","rag","empty"]{let mut ds=vec![];for branch in ["a","b"]{let get=|condition:&str|cells.iter().find(|c|s(c,"pair").ok()==Some(*pair)&&s(c,"branch").ok()==Some(branch)&&n(c,"day").ok()==Some(day as f64)&&s(c,"phase").ok()==Some("primary")&&s(c,"condition").ok()==Some(condition)).ok_or_else(||"Missing paired control".to_string()).and_then(|c|n(c,"creative_score"));ds.push(get("full")?-get(control)?);}differences.insert(control.to_string(),num(mean(&ds)));}contrasts.push(obj([("pair",text(*pair)),("day",num(day as f64)),("full_minus",Json::Object(differences))]));}}
 Ok(obj([("version",text("creative-life-ratings-2")),("source_proposals_sha256",text(hash.ok_or("missing source hash")?)),("mock",Json::Bool(mock)),("status",text(if mock{"technical_rehearsal_only"}else{"exploratory_blind_ratings"})),("independent_pairs",num(pairs.len() as f64)),("metric",text("Mean min(utility,originality), zero for invalid generation or failed constraints. Ordinal exploratory measure; not a validated creativity scale.")),("scored",arr(rows)),("cells",arr(cells)),("pairContrasts",arr(contrasts))]))
}
pub(super) fn summarize(dir:&Path)->Result<Json>{let design=load(&dir.join("life-design.json"))?;let mut checkpoints=vec![];for p in paths(&dir.join("checkpoints"))?{if !p.ends_with(".state.json"){continue;}let state=load(&dir.join("checkpoints").join(&p))?;let traces=array(&state,"traces")?;checkpoints.push(obj([("checkpoint",text(p)),("clock",state.get("clock")?.clone()),("traces",num(traces.len() as f64)),("latent",num(traces.iter().filter(|t|s(t,"status").ok()==Some("Latent")).count() as f64)),("axioms",state.get("axioms")?.clone()),("associations",state.get("associations")?.clone()),("mood",state.get("mood")?.clone())]));}
 let trials=load(&dir.join("all-proposals.json"))?;let task=design.get("fixture")?.get("tasks")?.array()?.first().ok_or("missing task")?.get("id")?;let mut layers=vec![];for t in trials.array()?{if s(t,"phase")?=="primary"||n(t,"repeat")?!=0.||t.get("task")?.get("id")?!=task{continue;}let mut row=obj([]);for k in ["pair","branch","phase","condition"]{row.put(k,t.get(k)?.clone());}row.put("context_words",t.get("generation")?.get("context_words")?.clone());if let Ok(v)=t.get("intervention").and_then(|x|x.get("removed_trace_ids")){row.put("removed_trace_ids",v.clone());}for k in ["selected_ids","axioms"]{if let Ok(v)=t.get("audit").and_then(|x|x.get(k)){row.put(k,v.clone());}}layers.push(row);}
 let mut choices=vec![];for p in paths(&dir.join("choices"))?{if p.ends_with(".json"){let c=load(&dir.join("choices").join(&p))?;let mut row=obj([("file",text(p)),("choice",c.get("choice")?.clone())]);if let Ok(v)=c.get("audit_only_world").and_then(|x|x.get("favored")){row.put("favored",v.clone());}choices.push(row);}}
 Ok(obj([("mock",design.get("provider")?.get("mock")?.clone()),("checkpoints",arr(checkpoints)),("layers",arr(layers)),("choices",arr(choices)),("claim",text("Availability and exposure audit only. Absent beliefs, latent traces or intervention effects must be reported."))]))}
fn paths(dir:&Path)->Result<Vec<String>>{let mut ps=fs::read_dir(dir).map_err(|e|e.to_string())?.map(|p|p.map(|p|p.file_name().to_string_lossy().into_owned()).map_err(|e|e.to_string())).collect::<Result<Vec<_>>>()?;ps.sort();Ok(ps)}
